import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, Component, EventEmitter, HostBinding, Input, Output, SimpleChanges } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  DateAdapter,
  MAT_DATE_FORMATS,
  MAT_DATE_LOCALE,
  MAT_NATIVE_DATE_FORMATS,
  MatNativeDateModule,
  NativeDateAdapter,
  provideNativeDateAdapter
} from '@angular/material/core';
import { MatDatepickerModule, MatDateRangePicker, MatDateRangeInput } from '@angular/material/datepicker';
import { MatInputModule } from '@angular/material/input';
import moment from 'moment'; // Correct default import
import { ButtonComponent } from '../button/button.component';


@Component({
  selector: 'datepicker',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [CommonModule, MatDatepickerModule, MatInputModule, MatNativeDateModule, FormsModule, ButtonComponent],
  providers: [
    provideNativeDateAdapter()
  ],
  templateUrl: './datepicker.component.html',
  styleUrls: ['./datepicker.component.scss']
})
export class DatepickerComponent {
  @Input() type: string = 'T';
  @Output() dateChange = new EventEmitter<any>();
  @Input() date: any;
  @Input() isRange: boolean = false;
  @HostBinding('class.bt-range')
  get hostBtRange(): boolean {
    return !!this.isRange;
  }
  @Input() disabled: boolean = false;
  selectedDate: Date;
  @Input() nolabel: boolean = false;
  @Input() defaultBlank: boolean = false;
  selectedStartDate: Date = new Date();
  selectedEndDate: Date = new Date();
  @Input() enableCustomAction: boolean = false;
  @Input() iconOnly: boolean = false;
  @Input() showrangelabel: boolean = false;
  @Input() disabledPrevious: boolean = false;
  today = new Date();
  @Input() noIcon: boolean = false;
  @Input() noPlaceholder: boolean = false;
  @Input() addcls: string = '';
  @Input() minDate: Date | null = new Date(1930, 0, 1); // January 1, 1930
  @Input() maxDate: Date | null = new Date(); // Current date

  constructor() { }

  ngOnInit(): void {
    if(this.type =='F'){
      // this.minDate = null;
      this.maxDate = new Date();
    }
    if (!this.defaultBlank)
      this.selectedDate = new Date()

    if (this.date) {
      if (this.isRange && Array.isArray(this.date)) {
        this.setRange(new Date(this.date[0]), new Date(this.date[1]));
      } else {
        this.setDate(new Date(this.date));
      }
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    //Called before any other lifecycle hook. Use it to inject dependencies, but avoid any serious work here.
    //Add '${implements OnChanges}' to the class.
    if (changes['date'] && !changes['date'].firstChange) { //this.date
      this.selectedDate = this.date;
      if (!this.date) {
        this.selectedStartDate = null;
        this.selectedEndDate = null;
      }
    }
    if (changes['disabled'] && !changes['disabled'].firstChange) {
      this.disabled = this.disabled;
    }
    if (changes['noIcon'] && !changes['noIcon'].firstChange) {
      this.noIcon = this.noIcon;
    }

    if (changes['noIcon']) {
      this.noIcon = this.noIcon;
    }

    if (changes['showrangelabel']) {
      this.showrangelabel = this.showrangelabel;
    }

    if (changes['addcls']) {
      this.addcls = this.addcls;
    }

  }

  onDateChange(e: any) {
    // this.dateChange.emit(value);
    const formattedDate = moment(new Date(e.value)).format('YYYY-MM-DD');
    this.dateChange.emit(formattedDate);
  }

  onRangeChange() {
    const start = moment(new Date(this.selectedStartDate)).format('YYYY-MM-DD');
    const end = moment(new Date(this.selectedEndDate)).format('YYYY-MM-DD');
    this.dateChange.emit([start, end]);
  }

  // Function to update the date programmatically
  setDate(date: Date) {
    this.selectedDate = date;
    this.dateChange.emit(date); // Optional: Emit the new date if needed
  }

  // Function to update the date range programmatically
  setRange(startDate: Date, endDate: Date) {
    this.selectedStartDate = startDate;
    this.selectedEndDate = endDate;
    this.dateChange.emit([startDate, endDate]); // Optional: Emit the new date range if needed
  }

  clearDate() {
    console.log("Clearing")
    this.setDate(null);
  }


  onPickerClosed() {
    if (this.selectedDate) {
    }
  }

  onPickerOpened() {
    console.log('Datepicker opened');
  }
}
